TYPE_OF_ERROR = ['typo', 'wrong_selection','missing_step','wrong_source', 'wrong_subnet', 'missing_permission','configuration_error']
def error_messages(error_type):
    if error_type == 'typo':
        return 'Typing error in configuration'
    
    elif error_type == 'wrong_selection':
        return 'You selected wrong optlon from dropdown'
    
    elif error_type == 'missing_step':
        return 'Forget to complete required step'
    
    elif error_type == 'wrong_source':
        return 'Incorrect source/destination specified'
    elif error_type == 'wrong_subnet':
        return 'Wrong subnets type selected'
    
    elif error_type == 'missing_permission':
        return 'You forgot to attach required permission'
    
    elif error_type == 'configuration_error':
        return 'Incorrect configuration for the step'
    else:
        return 'Unknown error'


def simulate_manual_deployment(timestamp=None):

    #6h 33mins will be used as my baseline since that is what I got in my own manual deployment
    duration_in_seconds = 23580
    random_success = random.random()
    
    #this is for 75% chance of success based on my manual deployment error rate
    if random_success < 0.75:
        success = True
        status = 'success'
        tests_failed = 0

    else:
        success = False
        status = 'failed'
        tests_failed = random.randint(1, 3)
    
    deployment = Deployment(
        deployment_type='manual',
        duration_seconds=duration_in_seconds, 
        status=status,
        timestamp=timestamp or datetime.utcnow(),
        triggered_by='Manual Simulation',
        tests_passed=success,
        #security_scan_passed=success,
        #security_vulnerabilities=0 if success else random.randint(1, 5),
        tests_total=5,
        tests_failed=tests_failed,
        errors_count=0
        
        
    )
    
    db.session.add(deployment)
    db.session.flush()  #gets deployment ID
    
    # Simulate errorrs based on error rates
    errors = []
    total_time_lost = 0
    for step in MANUAL_STEPS:
        random_error = random.random()
        if random_error < step['error_rate']:

            error_type = random.choice(TYPE_OF_ERROR)
            time_lost = random.randint(300, 1800)  
            error = DeploymentError(
                deployment_id=deployment.id,
                error_type=error_type,
                step_name=step['name'],
                error_message=error_messages(error_type),
                time_lost_seconds=time_lost
            )
            

            errors.append(error)

            total_time_lost += time_lost
            db.session.add(error)
    

    deployment.errors_count = len(errors)
    deployment.duration_seconds += total_time_lost
    
    db.session.commit()
    
    print(f"Simulated manual deployment: {deployment.duration_seconds}, {len(errors)} errors, {status}")
    
    return deployment


def simulate_multiple_deployments(count=10, spread_days=30):
    
    deployments = []
    
    #spread evenly
    total_seconds = spread_days * 24 * 60 * 60
    seconds_between = total_seconds / count
    
    current_time = datetime.utcnow() - timedelta(days=spread_days)
    
    for i in range(count):
        deployment = simulate_manual_deployment(timestamp=current_time)
        deployments.append(deployment)
        
        #move time forward for next deployment
        current_time = current_time + timedelta(seconds=seconds_between)

    """total_duration = 0
    index = 0
    while index < len(deployments):
        total_duration = total_duration + deployments[index].duration_seconds
        index = index + 1
        
    
    average_duration = total_duration / count"""

    


    success_count = 0
    for d in deployments:
        if d.status == 'success':
            success_count = success_count + 1
    
    success_rate = (success_count / count) * 100

    
    total_duration = 0
    for d in deployments:
        total_duration = total_duration + d.duration_seconds
    
    average_duration_hours = total_duration / count / 3600
    
    total_errors = 0
    for d in deployments:

        total_errors = total_errors + d.errors_count
    
    average_errors = total_errors / count
    
    print(f"\nSimulated {count} manual deployments")
    print(f"Success rate: {success_rate:.1f}%")
    print(f"Average duration: {average_duration_hours:.1f} hours")
    print(f"Average errors: {average_errors:.1f}")
    
    return deployments


def get_simulation_summary():
    
    manual_sims = Deployment.query.filter_by(
        deployment_type='manual',
        triggered_by='Manual Simulation'
    ).all()
    

    if not manual_sims:
        return {'message': 'No simulated deployments found'}
    
    count = len(manual_sims)
    success_count = sum(1 for d in manual_sims if d.status == 'success')
    success_rate = (success_count / count) * 100
    durations = [d.duration_seconds for d in manual_sims]
    total_duration = sum(durations)
    average_duration_hours = total_duration / count / 3600
    min_duration = min(durations)
    max_duration = max(durations)
    
    total_errors = sum(d.errors_count for d in manual_sims)
    average_errors = total_errors / count
    
    return {
        'count': count,
        'average_duration_hours': average_duration_hours,
        'min_duration': min_duration,
        'max_duration': max_duration,
        'success_rate': success_rate,
        'average_errors': average_errors,
        'total_errors': total_errors
    }